// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address owner = address(this);
        uint depositValue = 1 ether;
        vm.deal(owner, depositValue);
        address target = address(0x1234);
        c.sendMoney(target, depositValue);
        assertTrue(address(c).balance == 0);
    }
}
